<?php if($role==='admin'):
$selected=(int)($_GET['person']??0);$person=null;$attendanceRows=[];$leaveRows=[];$attendanceStats=['present_days'=>0,'absent_days'=>0,'break_days'=>0];$leaveTotals=['Paid Leave'=>['used'=>0,'pending'=>0],'Sick Leave'=>['used'=>0,'pending'=>0],'Casual Leave (LWP)'=>['used'=>0,'pending'=>0]];$balances=[];
if($selected){$st=$pdo->prepare('SELECT e.*,d.department_name FROM employees e LEFT JOIN departments d ON d.id=e.department_id WHERE e.id=?');$st->execute([$selected]);$person=$st->fetch();if($person){$st=$pdo->prepare("SELECT SUM(status IN ('Present','Late')) present_days,SUM(status='Absent') absent_days,SUM(status='On Break') break_days FROM attendance WHERE employee_id=? AND attendance_date BETWEEN ? AND ?");$st->execute([$selected,$dateFrom,$dateTo]);$attendanceStats=array_map('intval',$st->fetch()?:$attendanceStats);$st=$pdo->prepare('SELECT * FROM attendance WHERE employee_id=? AND attendance_date BETWEEN ? AND ? ORDER BY attendance_date DESC LIMIT 120');$st->execute([$selected,$dateFrom,$dateTo]);$attendanceRows=$st->fetchAll();$st=$pdo->prepare('SELECT * FROM leaves WHERE employee_id=? AND start_date<=? AND end_date>=? ORDER BY start_date DESC');$st->execute([$selected,$dateTo,$dateFrom]);$leaveRows=$st->fetchAll();foreach($leaveRows as $l){$days=ems_leave_workdays($pdo,max($dateFrom,$l['start_date']),min($dateTo,$l['end_date']));if(isset($leaveTotals[$l['leave_type']])){if($l['status']==='Approved')$leaveTotals[$l['leave_type']]['used']+=$days;elseif($l['status']==='Pending')$leaveTotals[$l['leave_type']]['pending']+=$days;}}$st=$pdo->prepare('SELECT leave_type,total_days FROM leave_balances WHERE employee_id=? AND leave_year=?');$st->execute([$selected,(int)date('Y')]);foreach($st->fetchAll() as $b)$balances[$b['leave_type']]=$b['total_days'];}}
?>
<div class="individual-report">
<section class="panel report-filter-panel"><div class="report-filter-heading"><div><span class="eyebrow">PEOPLE REPORT</span><h2>Individual employee report</h2></div></div><form method="get" class="filter-bar person-filter"><label class="search-field"><?=ems_icon('user')?><select name="person" required aria-label="Choose employee"><option value="">Choose employee</option><?php foreach($employees as $e):?><option value="<?=$e['id']?>" <?=$selected===(int)$e['id']?'selected':''?>><?=e($e['first_name'].' '.$e['last_name'].' · '.$e['employee_id'])?></option><?php endforeach;?></select></label><label>From<input type="date" name="from" value="<?=e($dateFrom)?>"></label><label>To<input type="date" name="to" value="<?=e($dateTo)?>"></label><button class="button primary">View report</button></form></section>
<?php if($person):?>
<section class="panel report-person-panel"><div class="report-person-header"><div><span class="eyebrow"><?=e($person['employee_id'])?> · <?=e($person['department_name']??'Unassigned')?></span><h2><?=e($person['first_name'].' '.$person['last_name'])?></h2><p><?=e($person['designation'])?> <span>·</span> Joined <?=e(date('M j, Y',strtotime($person['joining_date'])))?></p></div><div class="report-salary"><small>Salary</small><strong><?=$person['salary_amount']===null?'Not set':'₹'.number_format((float)$person['salary_amount'],2)?></strong></div></div>
<div class="kpi-grid report-kpis"><article class="kpi-card"><span class="kpi-label">Present & late</span><strong><?=$attendanceStats['present_days']?></strong><small>days</small></article><article class="kpi-card"><span class="kpi-label">Absent</span><strong><?=$attendanceStats['absent_days']?></strong><small>days</small></article><article class="kpi-card"><span class="kpi-label">On break</span><strong><?=$attendanceStats['break_days']?></strong><small>records</small></article><article class="kpi-card"><span class="kpi-label">Pending leave</span><strong><?=(int)$pdo->query("SELECT COUNT(*) FROM leaves WHERE employee_id=".(int)$selected." AND status='Pending'")->fetchColumn()?></strong><small>requests</small></article></div>
<div class="leave-balance-grid report-balances"><?php foreach(['Paid Leave','Sick Leave'] as $type):$usage=ems_leave_usage($pdo,$selected,$type,(int)date('Y'));$total=$balances[$type]??null;?><article class="balance-card"><div><b><?=e($type)?></b><small>Used <?=$usage['used']?> · Pending <?=$usage['pending']?> days</small></div><strong><?=$total===null?'Not set':number_format(max(0,(float)$total-$usage['used']),1).' days left'?></strong></article><?php endforeach;?><article class="balance-card"><div><b>Casual Leave (LWP)</b><small>Used <?=$leaveTotals['Casual Leave (LWP)']['used']?> · Pending <?=$leaveTotals['Casual Leave (LWP)']['pending']?> days</small></div><strong>Unpaid</strong></article></div>
<form method="post" class="balance-editor report-balance-editor"><?=csrf_field()?><input type="hidden" name="action" value="leave_balance_save"><input type="hidden" name="employee_id" value="<?=$selected?>"><input type="hidden" name="leave_year" value="<?=date('Y')?>"><span class="balance-editor-title">Yearly entitlement · <?=date('Y')?></span><?php foreach(['Paid Leave','Sick Leave'] as $type):?><label><?=e($type)?><input type="number" name="balances[<?=e($type)?>]" min="0" max="366" step="0.5" value="<?=e($balances[$type]??'')?>" placeholder="Not set"></label><?php endforeach;?><button class="button secondary">Save balances</button></form>
</section>
<section class="panel report-data-panel"><div class="panel-head"><div><h2>Attendance</h2><p><?=count($attendanceRows)?> records · <?=e($dateFrom.' to '.$dateTo)?></p></div></div><?php if($attendanceRows):table_attendance($attendanceRows,false);else:empty_state('clock','No attendance in this range','Choose a wider date range.');endif;?></section>
<section class="panel report-data-panel"><div class="panel-head"><div><h2>Leave history</h2></div></div><?php if($leaveRows):?><div class="table-wrap"><table><thead><tr><th>TYPE</th><th>DATES</th><th>WORK DAYS</th><th>STATUS</th><th>REASON</th></tr></thead><tbody><?php foreach($leaveRows as $l):?><tr><td><?=e($l['leave_type'])?></td><td><?=e($l['start_date'])?> – <?=e($l['end_date'])?></td><td><?=ems_leave_workdays($pdo,max($dateFrom,$l['start_date']),min($dateTo,$l['end_date']))?></td><td><?=status_badge($l['status'])?></td><td><?=e($l['reason'])?></td></tr><?php endforeach;?></tbody></table></div><?php else:empty_state('calendar','No leave requests','No leave requests in this date range.');endif;?></section>
<?php endif;?></div>
<?php endif;?>
